/// Browser context: Open or close a browser for this agent.
@MainActor
public enum BrowserContextAction {
    public static let id = "browser_context"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (BrowserContextInput) async throws -> BrowserContextOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (BrowserContextInput, Result<BrowserContextOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: BrowserContextInput) async throws -> BrowserContextOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct BrowserContextIntent: AppIntent {
    public static let title: LocalizedStringResource = "Browser context"
    public static let description = IntentDescription("Open or close a browser for this agent.")

    @Parameter(title: "Action", description: "open starts a new browser and returns its contextId; close shuts it and deletes its folder.")
    public var action: BrowserContextActionValue
    @Parameter(title: "Browser", description: "open only. fresh (default): empty legacy profile, outside copied-profile protection. mine: private copy of the person's profile with no saved-login stores, deleted on close. A failed mine open carries COPY_SOURCE_PERMISSION (the OS refused access; Desk cannot grant it) or COPY_SOURCE_POLICY (source qualification failed). The open reply's runtime names the Desk version and plugin root that ran.")
    public var browser: BrowserContextBrowserValue?
    @Parameter(title: "Context", description: "close only. The contextId that open returned.")
    public var contextId: String?

    public init() {}

    public init(_ input: BrowserContextInput) {
        self.init()
        self.action = input.action
        self.browser = input.browser
        self.contextId = input.contextId
    }

    public var input: BrowserContextInput {
        BrowserContextInput(action: action, browser: browser, contextId: contextId)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<BrowserContextOutput, any Error>
        do { result = .success(try await BrowserContextAction.run(input)) } catch { result = .failure(error) }
        if let dialog = BrowserContextAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

